from rdkit import Chem

# Parse the target molecule
target = "Cc1nc2ccc(-c3ccc([C@H](C)N4CC[C@](CC(C)(C)O)(c5ccccc5)OC4=O)cc3)cc2[nH]1"
mol = Chem.MolFromSmiles(target)

if mol:
    print("Target parsed successfully")
    print(f"Number of atoms: {mol.GetNumAtoms()}")

    # Find amide bonds
    for bond in mol.GetBonds():
        if bond.GetBondType() == Chem.BondType.AMIDE or (bond.GetBeginAtom().GetAtomicNum() == 6 and bond.GetEndAtom().GetAtomicNum() == 7):
            begin = bond.GetBeginAtom()
            end = bond.GetEndAtom()
            print(f"Bond between C{begin.GetIdx()} and N{end.GetIdx()}: {Chem.MolFragmentToSmiles(mol, atomsToUse=[begin.GetIdx(), end.GetIdx()])}")

    # Try to find the amide carbonyl
    for atom in mol.GetAtoms():
        if atom.GetAtomicNum() == 6:  # Carbon
            for neighbor in atom.GetNeighbors():
                if neighbor.GetAtomicNum() == 8 and atom.GetTotalValence() == 4:  # Oxygen double bond
                    print(f"Carbonyl carbon at index {atom.GetIdx()}, connected to O")
                    # Check what else is connected
                    for n2 in atom.GetNeighbors():
                        if n2.GetAtomicNum() != 8:
                            print(f"  Also connected to {n2.GetSymbol()} at index {n2.GetIdx()}")
else:
    print("Failed to parse target")
EOF
